(() => {
'use strict';
const paths={home:'<path d="m3 10 9-7 9 7v10H3z"/><path d="M9 20v-7h6v7"/>',music:'<path d="M9 18V5l11-2v13M9 8l11-2"/><ellipse cx="6" cy="18" rx="3" ry="3"/><ellipse cx="17" cy="16" rx="3" ry="3"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 6v6l4 2"/>',zones:'<rect x="3" y="3" width="7" height="7" rx="2"/><rect x="14" y="3" width="7" height="7" rx="2"/><rect x="3" y="14" width="7" height="7" rx="2"/><rect x="14" y="14" width="7" height="7" rx="2"/>',back:'<path d="m14 5-7 7 7 7"/>',next:'<path d="m8 5 9 7-9 7M19 5v14"/>',prev:'<path d="m16 5-9 7 9 7M5 5v14"/>',volume:'<path d="M11 4 5 9H2v6h3l6 5zM15 8a6 6 0 010 8M18 5a10 10 0 010 14"/>',heart:'<path d="M12 20 4 12C-2 5 8 0 12 7c4-7 14-2 8 5z"/>',play:'<path d="M8 4.5 20 12 8 19.5z"/>',pause:'<rect x="6" y="4" width="4" height="16" rx="1"/><rect x="14" y="4" width="4" height="16" rx="1"/>'};
const icon=n=>'<svg viewBox="0 0 24 24" aria-hidden="true">'+paths[n]+'</svg>';
document.querySelectorAll('[data-icon]').forEach(x=>x.innerHTML=icon(x.dataset.icon));
const tracks=[{name:'Morning Soul',who:'Nico',genre:'Soul · Jazz · Bossa Nova',line:'Хорошее утро начинается со звука.'},{name:'Coffee Stories',who:'Sandra',genre:'Lounge · Acoustic · Soul',line:'Для тёплых встреч и ещё одной чашки.'},{name:'Night Groove',who:'Leo',genre:'Funk · Disco · Nu-disco',line:'У вечера свои планы.'},{name:'Soft Motion',who:'Mia',genre:'Ambient · Chill · Wellness',line:'Вдохните. Всё в вашем ритме.'}];
const content=document.querySelector('#content'),audio=document.querySelector('#audio');let current=0,screen='home',day=0,toastTimer,playRequest=0;const favorites=new Set();const schedules=Array.from({length:7},()=>[0,1,2,3]);const zones=[{name:'Основной зал',detail:'Кофейня на углу',volume:65,enabled:true,track:0},{name:'Терраса',detail:'Открытое пространство',volume:40,enabled:true,track:1},{name:'Лаунж',detail:'Тихая зона',volume:25,enabled:false,track:3}];
audio.volume=.65;
const toy=i=>'<span class="toy t'+i+'"></span>';
const toast=text=>{const el=document.querySelector('#toast');el.textContent=text;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2800)};
function sync(){document.body.classList.toggle('playing',!audio.paused);document.querySelectorAll('.play').forEach(b=>{b.innerHTML=icon(audio.paused?'play':'pause');b.setAttribute('aria-label',audio.paused?'Слушать эскиз':'Пауза');b.setAttribute('aria-pressed',String(!audio.paused))});document.querySelector('#mini-title').textContent=tracks[current].name;document.querySelector('#mini-cover').className='mini-cover toy t'+current;document.querySelector('#mini-state').textContent=audio.paused?'Музыкальный эскиз · пауза':'Играет эскиз · '+tracks[current].genre;document.querySelectorAll('.current-title').forEach(x=>x.textContent=tracks[current].name)}
async function play(){if(!audio.paused){playRequest++;audio.pause();sync();return}const id=++playRequest;try{await audio.play();if(id===playRequest)sync()}catch(e){if(id===playRequest&&e.name!=='AbortError')toast('Не удалось включить аудио. Попробуйте ещё раз.')}}
function choose(i,open=true){playRequest++;audio.pause();current=i;audio.src='/assets/preview-'+i+'.wav';if(open)render('player');sync()}
const options=selected=>tracks.map((t,i)=>'<option value="'+i+'" '+(selected===i?'selected':'')+'>'+t.name+'</option>').join('');
function home(){return '<div class="greeting"><div><div class="overline">ВАШЕ ПРОСТРАНСТВО</div><h2>Кофейня на углу</h2><p>Пусть сегодня звучит красиво.</p></div></div><div class="hero-card"><img src="/assets/hero-v5.webp" alt="Виниловый Нико в очках и наушниках над миниатюрной кофейней"><span class="hero-label">YOUR SPACE. YOUR SOUND.</span><div class="hero-caption"><div><small>НАСТРОЕНИЕ ДНЯ</small><strong class="current-title">'+tracks[current].name+'</strong></div><button class="play" aria-label="Слушать эскиз"></button></div></div><div class="quick-grid"><button class="quick" data-screen="zones">'+icon('zones')+'<strong>3 музыкальные зоны</strong><small>Настроить пространство</small></button><button class="quick" data-screen="schedule">'+icon('clock')+'<strong>В ритме дня</strong><small>4 настроения в расписании</small></button></div><div class="section-title"><h3>Ваш музыкальный характер</h3><button data-screen="music">Все герои</button></div><div class="moods" aria-label="Подборки, листайте горизонтально">'+tracks.map((t,i)=>'<button class="mood" data-track="'+i+'">'+toy(i)+'<span class="mood-text"><strong>'+t.who+'</strong><small>'+t.name+'</small></span></button>').join('')+'</div><p class="note">Демо заведения. Настройки не меняют реальный эфир.</p><div class="credit">Design by <b>Promo.Art</b></div>'}
function music(){return '<div class="overline">ВЫБЕРИТЕ СВОЁ ЗВУЧАНИЕ</div><h2 class="screen-title">Музыка с характером</h2><p class="screen-intro">У каждого места свой герой. Познакомьтесь с четырьмя настроениями.</p><div class="music-list">'+tracks.map((t,i)=>'<button class="track '+(current===i?'selected':'')+'" data-track="'+i+'">'+toy(i)+'<span><span class="badge">'+t.who+'</span><strong>'+t.name+'</strong><small>'+t.genre+'</small></span></button>').join('')+'</div><p class="note" style="margin-top:20px">Короткие инструментальные эскизы для знакомства с интерфейсом. Не каталог сервиса.</p>'}
function player(){const t=tracks[current];return '<div class="back-row"><button class="icon-button" data-screen="music" aria-label="К подборкам">'+icon('back')+'</button><small>ВАШЕ НАСТРОЕНИЕ</small><span class="tag">ЭСКИЗ</span></div><div class="big-art">'+toy(current)+'<span class="chip">'+t.who+' / '+t.line+'</span></div><div class="player-heading"><div><h2>'+t.name+'</h2><p>'+t.genre+'</p></div><button class="icon-button heart '+(favorites.has(current)?'active':'')+'" id="favorite" aria-label="В избранное" aria-pressed="'+favorites.has(current)+'">'+icon('heart')+'</button></div><div class="equalizer" aria-hidden="true">'+Array.from({length:34},(_,i)=>'<i style="--i:'+i+'"></i>').join('')+'</div><div class="time-row"><span id="elapsed">0:00</span><span>НА ПОВТОРЕ</span></div><div class="transport"><button class="icon-button" id="prev" aria-label="Предыдущая подборка">'+icon('prev')+'</button><button class="play" aria-label="Слушать эскиз"></button><button class="icon-button" id="next" aria-label="Следующая подборка">'+icon('next')+'</button></div><label class="volume">'+icon('volume')+'<input id="volume" aria-label="Громкость прослушивания" type="range" min="0" max="100" value="'+Math.round(audio.volume*100)+'"><output>'+Math.round(audio.volume*100)+'%</output></label><p class="note">Звук воспроизводится на этом устройстве.</p>'}
function schedule(){return '<div class="overline">МУЗЫКА МЕНЯЕТСЯ ВМЕСТЕ С ДНЁМ</div><h2 class="screen-title">Ваш ритм дня</h2><p class="screen-intro">Мягкое утро, оживлённый день, тёплый вечер. Выберите настроение для каждого часа.</p><div class="week">'+['Пн','Вт','Ср','Чт','Пт','Сб','Вс'].map((d,i)=>'<button data-day="'+i+'" class="'+(day===i?'active':'')+'" aria-pressed="'+(day===i)+'">'+d+'</button>').join('')+'</div>'+['09:00','13:00','18:00','22:00'].map((h,i)=>'<div class="schedule-row"><time>'+h+'</time><label>'+['ХОРОШЕЕ НАЧАЛО','ВРЕМЯ ВСТРЕЧ','ВЕЧЕРНИЙ ГРУВ','МЯГКОЕ ЗАВЕРШЕНИЕ'][i]+'<select data-slot="'+i+'" aria-label="Музыка в '+h+'">'+options(schedules[day][i])+'</select></label></div>').join('')+'<button class="primary" id="save-schedule">Сохранить расписание</button><p class="note">Демо: сохранение только в этом браузере. Время показано условно, без подключения к часовому поясу заведения.</p>'}
function zoneScreen(){return '<div class="overline">КАЖДОМУ ПРОСТРАНСТВУ СВОЙ ЗВУК</div><h2 class="screen-title">Музыкальные зоны</h2><p class="screen-intro">От зала до террасы. Настройте настроение каждой зоны.</p>'+zones.map((z,i)=>'<article class="zone-card"><div class="zone-head"><div><strong>'+z.name+'</strong><small>'+z.detail+'</small></div><button class="toggle" data-zone-toggle="'+i+'" aria-label="Включить зону '+z.name+'" aria-pressed="'+z.enabled+'"></button></div><select data-zone-track="'+i+'" aria-label="Музыка: '+z.name+'">'+options(z.track)+'</select><label class="volume">'+icon('volume')+'<input data-zone-volume="'+i+'" aria-label="Громкость: '+z.name+'" type="range" min="0" max="100" value="'+z.volume+'"><output>'+z.volume+'%</output></label></article>').join('')+'<p class="note">Демонстрационные зоны. Устройства не подключены; ползунки не меняют звук реального заведения.</p>'}
function profile(){return '<div class="overline">ВАШ PROMO.AIR</div><h2 class="screen-title">Моё пространство</h2><div class="profile-card">'+toy(0)+'<h3>Кофейня на углу</h3><p>Пример профиля заведения</p><span class="tag">ДЕМО АККАУНТА</span></div><a class="profile-link" href="/cabinet/">Веб-кабинет<small>Управление заведениями на большом экране</small></a><a class="profile-link" href="/promo-air/legal-music/#plans">Тарифы и подключение<small>7 дней без оплаты</small></a><a class="profile-link" href="/promo-air/own-radio/">Собственное радио<small>Джинглы, анонсы и голос бренда</small></a><a class="profile-link" href="https://promo-music.ru/login">Войти в действующий кабинет<small>PROMO.MUSIC</small></a><div class="credit">Design by <b>Promo.Art</b></div>'}
function render(next){screen=next;const pages={home,music,player,schedule,zones:zoneScreen,profile};content.innerHTML=pages[screen]();content.scrollTop=0;document.querySelectorAll('nav [data-screen]').forEach(b=>{if(b.dataset.screen===(screen==='player'?'music':screen))b.setAttribute('aria-current','page');else b.removeAttribute('aria-current')});document.querySelector('.mini-player').style.display=screen==='player'?'none':'flex';sync();bind()}
function bind(){content.querySelectorAll('[data-track]').forEach(b=>b.onclick=()=>choose(+b.dataset.track));content.querySelectorAll('[data-day]').forEach(b=>b.onclick=()=>{day=+b.dataset.day;render('schedule')});content.querySelectorAll('[data-slot]').forEach(s=>s.onchange=()=>schedules[day][+s.dataset.slot]=+s.value);const save=content.querySelector('#save-schedule');if(save)save.onclick=()=>{try{localStorage.setItem('promo-air-app-schedule',JSON.stringify(schedules));toast('Демо-расписание сохранено в браузере')}catch{toast('Сохранение недоступно. Настройки остаются до закрытия страницы.')}};content.querySelectorAll('[data-zone-toggle]').forEach(b=>b.onclick=()=>{const z=zones[+b.dataset.zoneToggle];z.enabled=!z.enabled;b.setAttribute('aria-pressed',String(z.enabled));toast('Демо: зона '+(z.enabled?'включена':'выключена'))});content.querySelectorAll('[data-zone-track]').forEach(s=>s.onchange=()=>zones[+s.dataset.zoneTrack].track=+s.value);content.querySelectorAll('[data-zone-volume]').forEach(s=>s.oninput=()=>{zones[+s.dataset.zoneVolume].volume=+s.value;s.nextElementSibling.textContent=s.value+'%'});const vol=content.querySelector('#volume');if(vol)vol.oninput=()=>{audio.volume=+vol.value/100;vol.nextElementSibling.textContent=vol.value+'%'};const fav=content.querySelector('#favorite');if(fav)fav.onclick=()=>{if(favorites.has(current))favorites.delete(current);else favorites.add(current);fav.classList.toggle('active',favorites.has(current));fav.setAttribute('aria-pressed',String(favorites.has(current)));toast(favorites.has(current)?'В избранном на время просмотра':'Убрано из избранного')};const prev=content.querySelector('#prev'),next=content.querySelector('#next');if(prev)prev.onclick=()=>choose((current+3)%4);if(next)next.onclick=()=>choose((current+1)%4)}
document.addEventListener('click',e=>{const b=e.target.closest('[data-screen]');if(b)render(b.dataset.screen);if(e.target.closest('.play'))play()});document.querySelector('#open-player').onclick=()=>render('player');audio.addEventListener('playing',sync);audio.addEventListener('pause',sync);audio.addEventListener('error',()=>{sync();toast('Эскиз недоступен. Выберите другую подборку.')});audio.addEventListener('timeupdate',()=>{const el=document.querySelector('#elapsed');if(el)el.textContent=Math.floor(audio.currentTime/60)+':'+String(Math.floor(audio.currentTime%60)).padStart(2,'0')});
try{const saved=JSON.parse(localStorage.getItem('promo-air-app-schedule'));if(Array.isArray(saved)&&saved.length===7&&saved.every(d=>Array.isArray(d)&&d.length===4&&d.every(n=>Number.isInteger(n)&&n>=0&&n<4)))saved.forEach((d,i)=>schedules[i]=d)}catch{}
render('home');
})();
